    });
    // 可见点
    vis.forEach(function (r) {
      var cls = 'pt' + (st.sel.has(r.id) ? ' sel' : '') + (App.state.pins.has(r.id) ? ' pinned' : '');
      s += pt(r, sx, sy, sizeSc, ' ' + cls);
