/* 星穹棱镜 Prism · 深色高密度探索台 */
* { box-sizing: border-box; margin: 0; padding: 0; }
:root {
  --bg: #0d1117; --panel: #141b24; --panel2: #1a2330; --line: #2a3646;
  --tx: #dbe4ef; --tx2: #8496ab; --acc: #5ab4f0; --warn: #f0975a;
  --sel: #ffd166; --filt: #e0566e;
}
html, body { height: 100%; }
body {
  background: var(--bg); color: var(--tx);
  font: 13px/1.45 "Segoe UI", "Microsoft YaHei", system-ui, sans-serif;
  display: flex; flex-direction: column; overflow: hidden;
}
#errbox { display: none; background: #5b1620; color: #ffd7dc; padding: 6px 14px; font-size: 12px; }
button { font: inherit; cursor: pointer; border: 1px solid var(--line); background: var(--panel2); color: var(--tx); border-radius: 5px; }
button:hover { border-color: var(--acc); }
button:disabled { opacity: .35; cursor: default; }
.spacer { flex: 1; }
.hidden { display: none !important; }

/* ---------- 顶栏 ---------- */
#topbar { display: flex; align-items: center; gap: 14px; padding: 8px 14px; background: var(--panel); border-bottom: 1px solid var(--line); }
.brand { display: flex; align-items: center; gap: 9px; }
.brand .logo { font-size: 24px; color: var(--acc); line-height: 1; }
.brand h1 { font-size: 15px; font-weight: 600; letter-spacing: .5px; }
.brand h1 em { color: var(--acc); font-style: normal; font-weight: 400; font-size: 12px; margin-left: 2px; }
.brand .sub { font-size: 11px; color: var(--tx2); }
.datastat { font-size: 12px; color: var(--tx2); padding-left: 12px; border-left: 1px solid var(--line); }
.datastat b { color: var(--tx); font-size: 13px; }
.lensbox { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--tx2); }
.lensbox input { background: var(--panel2); border: 1px solid var(--line); color: var(--warn); border-radius: 5px; padding: 3px 8px; width: 110px; font-size: 12px; }
.histbtns { display: flex; gap: 6px; }
button.ghost { background: transparent; padding: 4px 10px; font-size: 12px; color: var(--tx2); }
button.ghost:not(:disabled):hover { color: var(--tx); }
button.sm { padding: 2px 8px; font-size: 11px; }

/* ---------- 主布局 ---------- */
#layout { flex: 1; display: flex; min-height: 0; }
.panelhead { display: flex; align-items: center; gap: 8px; padding: 9px 12px 6px; }
.panelhead h2 { font-size: 12px; font-weight: 600; color: var(--tx); letter-spacing: 1px; }
.hint { font-size: 11px; color: var(--tx2); }

/* 左：维度货架 */
#shelf { width: 272px; min-width: 272px; overflow-y: auto; background: var(--panel); border-right: 1px solid var(--line); }
.shelfhelp { font-size: 11px; color: var(--tx2); padding: 0 12px 8px; border-bottom: 1px solid var(--line); }
.dimgroup { font-size: 10.5px; color: var(--tx2); letter-spacing: 1px; padding: 10px 12px 4px; }
.dim { padding: 5px 12px 7px; border-bottom: 1px solid rgba(42,54,70,.5); }
.dim.filtered { background: rgba(224,86,110,.07); }
.dimrow { display: flex; align-items: center; gap: 6px; }
.dname { font-size: 12.5px; }
.dunit { font-size: 10.5px; color: var(--tx2); }
.fbadge { font-size: 10px; color: #ffb3c0; background: rgba(224,86,110,.18); border-color: rgba(224,86,110,.4); padding: 0 6px; border-radius: 8px; }
button.ax { font-size: 10px; width: 20px; height: 18px; padding: 0; color: var(--tx2); }
button.ax.on { background: var(--acc); border-color: var(--acc); color: #06121f; font-weight: 700; }
.spark { display: block; margin-top: 3px; }
.spark .hb { fill: #3d5a78; }
.spark .hb.dim { fill: #26313f; }
.spark .frange { fill: rgba(224,86,110,.22); stroke: var(--filt); stroke-width: 1; }
.spark .frange.drag { fill: rgba(90,180,240,.25); stroke: var(--acc); }
.spark .dragzone { fill: transparent; cursor: ew-resize; }
.dext { font-size: 10px; color: var(--tx2); margin-top: 2px; }
.catvals { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 4px; }
button.cv { display: flex; align-items: center; gap: 4px; font-size: 11px; padding: 2px 7px; border-radius: 9px; }
button.cv em { font-style: normal; color: var(--tx2); font-size: 10px; }
button.cv .cb { width: 8px; height: 8px; border-radius: 2px; background: var(--line); display: inline-block; }
button.cv.on { color: var(--tx); border-color: #3d5a78; }
button.cv.on .cb { background: var(--acc); }
button.cv.off { opacity: .45; text-decoration: line-through; }

/* 中：图区 */
#stage { flex: 1; display: flex; flex-direction: column; min-width: 0; }
#plotbar { display: flex; align-items: center; gap: 10px; padding: 7px 14px; border-bottom: 1px solid var(--line); background: rgba(20,27,36,.6); }
.plot-title { font-size: 13px; font-weight: 600; }
.plot-title i { color: var(--tx2); font-style: normal; padding: 0 2px; }
.plotmeta { font-size: 11px; color: var(--tx2); font-weight: 400; margin-left: 6px; }
label.enc { font-size: 11.5px; color: var(--tx2); display: flex; align-items: center; gap: 5px; }
label.enc select { background: var(--panel2); color: var(--tx); border: 1px solid var(--line); border-radius: 5px; padding: 2px 6px; font-size: 11.5px; }
#plotwrap { flex: 1; position: relative; min-height: 0; }
#plot { display: block; }
.gridl, .tick, .axisname, .pinstar { pointer-events: none; }
.gridl { stroke: #212c3a; stroke-width: 1; }
.tick { fill: var(--tx2); font-size: 10px; }
.axisname { fill: var(--tx2); font-size: 11.5px; }
circle.pt { stroke: rgba(6,12,20,.55); stroke-width: .8; cursor: pointer; }
circle.pt:hover { stroke: #fff; stroke-width: 1.2; }
circle.pt.sel { stroke: var(--sel); stroke-width: 2.2; }
circle.pt.pinned { filter: drop-shadow(0 0 3px var(--sel)); }
circle.ghostpt { fill: none !important; stroke: #55647a; stroke-width: 1.3; stroke-dasharray: 2 2; opacity: .8; }
.pinstar { fill: var(--sel); font-size: 11px; pointer-events: none; }
#brushbox { fill: rgba(90,180,240,.14); stroke: var(--acc); stroke-width: 1; stroke-dasharray: 3 2; }
#tooltip { position: absolute; pointer-events: none; background: #0a0f16ee; border: 1px solid var(--line); border-radius: 6px; padding: 7px 10px; font-size: 11.5px; z-index: 5; max-width: 260px; }
#legend { position: absolute; top: 8px; right: 12px; background: #0a0f16cc; border: 1px solid var(--line); border-radius: 6px; padding: 5px 9px; font-size: 11px; display: flex; flex-wrap: wrap; gap: 7px; align-items: center; max-width: 420px; }
#legend b { color: var(--tx2); font-weight: 400; margin-right: 2px; }
.lg { display: inline-flex; align-items: center; gap: 4px; }
.lg i { width: 9px; height: 9px; border-radius: 50%; display: inline-block; }
.lg em { font-style: normal; color: var(--tx2); font-size: 10px; }

/* 右：锚点/详情 */
#side { width: 300px; min-width: 300px; overflow-y: auto; background: var(--panel); border-left: 1px solid var(--line); }
.anchorbar { display: flex; gap: 8px; padding: 2px 12px 8px; }
.acard { flex: 1; background: var(--panel2); border: 1px solid var(--line); border-radius: 7px; padding: 6px 9px; font-size: 11px; color: var(--tx2); }
.acard b { display: block; font-size: 17px; color: var(--sel); }
.subhead { font-size: 11.5px; color: var(--tx2); padding: 8px 12px 4px; letter-spacing: 1px; }
.subhead .cnt { color: var(--sel); }
.reclist { max-height: 148px; overflow-y: auto; }
.rec { display: flex; align-items: center; gap: 6px; padding: 3px 12px; cursor: pointer; border-left: 2px solid transparent; }
.rec:hover { background: var(--panel2); }
.rec.rec-sel { border-left-color: var(--sel); }
.recname { font-size: 12px; }
.recmeta { font-size: 10.5px; color: var(--tx2); flex: 1; text-align: right; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
button.unpin { border: none; background: none; color: var(--tx2); font-size: 11px; padding: 0 2px; }
button.unpin:hover { color: var(--sel); }
.dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; flex: none; }
.empty { font-size: 11px; color: var(--tx2); padding: 4px 12px 8px; }
.ghostline { font-size: 10.5px; color: #6d7c92; padding: 3px 12px; }
.dcard { margin: 4px 12px 14px; background: var(--panel2); border: 1px solid var(--line); border-radius: 8px; padding: 9px 11px; }
.dcard h3 { font-size: 13px; margin-bottom: 6px; display: flex; align-items: center; gap: 6px; }
.dcard table { width: 100%; border-collapse: collapse; }
.dcard td { padding: 2px 0; font-size: 11.5px; color: var(--tx2); border-bottom: 1px dashed #222d3c; }
.dcard td:last-child { text-align: right; color: var(--tx); }
.sibhead { font-size: 11px; color: var(--tx2); margin: 8px 0 4px; }
.sibs { display: flex; flex-wrap: wrap; gap: 4px; }
button.sib { font-size: 11px; padding: 1px 7px; border-radius: 8px; }

/* 底：状态归属条 */
#statebar { display: flex; align-items: flex-start; gap: 10px; padding: 7px 14px; background: var(--panel); border-top: 1px solid var(--line); min-height: 42px; flex-wrap: wrap; }
.barhead { font-size: 11.5px; color: var(--tx2); padding-top: 3px; white-space: nowrap; }
.barhead b { color: var(--tx); }
#chips { display: flex; flex-wrap: wrap; gap: 5px; flex: 1; }
.chip { display: inline-flex; align-items: center; gap: 5px; font-size: 11px; padding: 2px 9px; border-radius: 9px; border: 1px solid var(--line); background: var(--panel2); }
.chip .src { font-style: normal; font-size: 9.5px; color: #06121f; background: var(--tx2); border-radius: 4px; padding: 0 4px; }
.chip.proj { border-color: #33506e; }
.chip.proj .src { background: var(--acc); }
.chip.filt { border-color: rgba(224,86,110,.55); color: #ffc4ce; }
.chip.filt .src { background: var(--filt); }
.chip[data-remove] { cursor: pointer; }
.chip[data-remove]:hover { border-color: var(--warn); }
.chip .x { color: var(--tx2); font-weight: 400; }
.chip.anchor { border-style: dashed; color: var(--sel); border-color: rgba(255,209,102,.4); }

/* 历史抽屉 */
#histDrawer { position: fixed; right: 310px; top: 56px; bottom: 46px; width: 330px; background: #101722f5; border: 1px solid var(--line); border-radius: 10px; z-index: 20; overflow-y: auto; box-shadow: -8px 0 28px rgba(0,0,0,.5); }
.drawerhelp { font-size: 11px; color: var(--tx2); padding: 0 14px 8px; border-bottom: 1px solid var(--line); }
#histList { list-style: none; padding: 6px 0; }
#histList li { display: flex; align-items: center; gap: 8px; padding: 4px 14px; cursor: pointer; border-left: 2px solid transparent; font-size: 11.5px; }
#histList li:hover { background: var(--panel2); }
#histList li.cur { border-left-color: var(--acc); background: rgba(90,180,240,.08); }
#histList li.future { opacity: .38; }
.htime { color: var(--tx2); font-size: 10px; flex: none; }
.hlabel { flex: 1; }
.htag { color: var(--acc); font-weight: 400; font-size: 10px; }

::-webkit-scrollbar { width: 9px; height: 9px; }
::-webkit-scrollbar-thumb { background: #2a3646; border-radius: 5px; }
::-webkit-scrollbar-track { background: transparent; }

