1	/* 星穹棱镜 · 状态层：投影/过滤状态、归属条、可回退历史、认知锚点 */
2	window.App = (function () {
3	  'use strict';
4	
5	  var state = {
6	    x: 'radius', y: 'temp',      // 投影轴
7	    color: 'spec', size: null,   // 视觉编码
8	    filters: [],                 // [{id,dim,kind,lo,hi,values,src}]
9	    sel: new Set(),              // 选中（认知锚点：不随投影/回退重置）
10	    pins: new Set()              // 固定（认知锚点）
11	  };
12	
13	  var hist = [], hptr = -1, fid = 0;
14	  var renderers = [];
15	  var hoveredId = null, detailId = null;
16	
17	  /* ---------- 工具 ---------- */
18	  function dimByKey(k) {
19	    var i;
20	    for (i = 0; i < Data.NUMS.length; i++) if (Data.NUMS[i].key === k) return Data.NUMS[i];
21	    for (i = 0; i < Data.CATS.length; i++) if (Data.CATS[i].key === k) return Data.CATS[i];
22	    for (i = 0; i < Data.HIER.length; i++) if (Data.HIER[i].key === k) return Data.HIER[i];
23	    return null;
24	  }
25	  function isNumDim(k) { var d = dimByKey(k); return d && Data.NUMS.indexOf(d) >= 0; }
26	  function fmtV(k, v) {
27	    var d = dimByKey(k);
28	    if (!d) return String(v);
29	    if (Data.NUMS.indexOf(d) >= 0) return d.dp ? (+v).toFixed(d.dp) : String(v);
30	    return String(v);
31	  }
32	  function esc(s) {
33	    return String(s).replace(/[&<>"]/g, function (c) {
34	      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c];
35	    });
36	  }
37	
38	  /* ---------- 过滤语义 ---------- */
39	  function matchFilter(r, f) {
40	    if (f.kind === 'range') return r[f.dim] >= f.lo && r[f.dim] <= f.hi;
41	    return f.values.indexOf(r[f.dim]) >= 0;
42	  }
43	  function visibleRows() {
44	    return Data.rows.filter(function (r) {
45	      for (var i = 0; i < state.filters.length; i++)
46	        if (!matchFilter(r, state.filters[i])) return false;
47	      return true;
48	    });
49	  }
50	  function filterLabel(f) {
51	    var d = dimByKey(f.dim);
52	    if (f.kind === 'range') {
53	      return d.name + ' ∈ [' + fmtV(f.dim, f.lo) + ', ' + fmtV(f.dim, f.hi) + '] ' + d.unit;
54	    }
55	    return d.name + ' ⊇ {' + f.values.join('，') + '}';
56	  }
57	
58	  /* ---------- 历史（过滤+投影可回退；选中/固定不入历史） ---------- */
59	  function snap() {
60	    return {
61	      x: state.x, y: state.y, color: state.color, size: state.size,
62	      filters: JSON.parse(JSON.stringify(state.filters))
63	    };
64	  }
65	  function restore(s) {
66	    state.x = s.x; state.y = s.y; state.color = s.color; state.size = s.size;
67	    state.filters = JSON.parse(JSON.stringify(s.filters));
68	  }
69	  function commit(label, fn) {
70	    fn(state);
71	    hist = hist.slice(0, hptr + 1);
72	    hist.push({ label: label, t: new Date(), snap: snap() });
73	    hptr = hist.length - 1;
74	    render();
75	  }
76	  function undo() { if (hptr > 0) { hptr--; restore(hist[hptr].snap); render(); } }
77	  function redo() { if (hptr < hist.length - 1) { hptr++; restore(hist[hptr].snap); render(); } }
78	  function jump(i) { hptr = i; restore(hist[i].snap); render(); }
79	
80	  /* ---------- 过滤变更 API（供货架/图区调用） ---------- */
81	  function addRangeFilter(dim, lo, hi, src) {
82	    commit('过滤 ' + dimByKey(dim).name + ' ∈ [' + fmtV(dim, lo) + ', ' + fmtV(dim, hi) + ']',
83	      function (st) { st.filters.push({ id: 'f' + (fid++), dim: dim, kind: 'range', lo: lo, hi: hi, src: src }); });
84	  }
85	  function toggleCatFilter(dim, val) {
86	    var existed = state.filters.filter(function (f) { return f.kind === 'cat' && f.dim === dim; })[0];
87	    var label = dimByKey(dim).name + ' ' + val;
88	    commit((existed ? '调整' : '过滤 ') + label, function (st) {
89	      var f = st.filters.filter(function (g) { return g.kind === 'cat' && g.dim === dim; })[0];
90	      if (!f) {
91	        var vals = dimByKey(dim).values.filter(function (v) { return v !== val; });
92	        st.filters.push({ id: 'f' + (fid++), dim: dim, kind: 'cat', values: vals, src: '类别勾选' });
93	      } else {
94	        var i = f.values.indexOf(val);
95	        if (i >= 0) f.values.splice(i, 1); else f.values.push(val);
96	        if (f.values.length === dimByKey(dim).values.length)
97	          st.filters = st.filters.filter(function (g) { return g !== f; });
98	      }
99	    });
100	  }
101	  function catChecked(dim, val) { // 该值当前是否被包含（无过滤=全包含）
102	    var f = state.filters.filter(function (g) { return g.kind === 'cat' && g.dim === dim; })[0];
103	    return !f || f.values.indexOf(val) >= 0;
104	  }
105	  function removeFilter(id) {
106	    var f = state.filters.filter(function (g) { return g.id === id; })[0];
107	    commit('移除过滤：' + (f ? filterLabel(f) : id), function (st) {
108	      st.filters = st.filters.filter(function (g) { return g.id !== id; });
109	    });
110	  }
111	  function clearFilters() {
112	    commit('清除全部 ' + state.filters.length + ' 个过滤', function (st) { st.filters = []; });
113	  }
114	  function setAxis(axis, dim) {
115	    if (state[axis] === dim) return;
116	    commit((axis === 'x' ? 'X 轴 → ' : 'Y 轴 → ') + dimByKey(dim).name, function (st) { st[axis] = dim; });
117	  }
118	  function setEnc(which, dim) {
119	    commit((which === 'color' ? '颜色 → ' : '大小 → ') + (dim ? dimByKey(dim).name : '无'),
120	      function (st) { st[which] = dim; });
121	  }
122	
123	  /* ---------- 锚点操作（不入历史，实时生效） ---------- */
124	  function toggleSel(id) {
125	    if (state.sel.has(id)) state.sel.delete(id); else state.sel.add(id);
126	    render();
127	  }
128	  function setSel(ids) { state.sel = new Set(ids); render(); }
129	  function clearSel() { state.sel.clear(); render(); }
130	  function togglePin(id) {
131	    if (state.pins.has(id)) state.pins.delete(id); else state.pins.add(id);
132	    render();
133	  }
134	  function setHover(id) { hoveredId = id; render(); }
135	  function setDetail(id) { detailId = id; render(); }
136	
137	  /* ---------- 渲染调度 ---------- */
138	  function render() {
139	    renderers.forEach(function (fn) { fn(); });
140	    document.getElementById('undoBtn').disabled = hptr <= 0;
141	    document.getElementById('redoBtn').disabled = hptr >= hist.length - 1;
142	  }
143	
144	  /* ---------- 底部归属条 ---------- */
145	  function renderChips() {
146	    var vis = visibleRows();
147	    var hidden = 0;
148	    Data.rows.forEach(function (r) { if (state.sel.has(r.id)) hidden++; });
149	    hidden = hidden - vis.filter(function (r) { return state.sel.has(r.id); }).length;
150	
151	    var html = '';
152	    html += chip('proj', 'X · ' + dimByKey(state.x).name, null, '投影');
153	    html += chip('proj', 'Y · ' + dimByKey(state.y).name, null, '投影');
154	    if (state.color) html += chip('proj', '颜色 · ' + dimByKey(state.color).name, 'color', '编码');
155	    if (state.size) html += chip('proj', '大小 · ' + dimByKey(state.size).name, 'size', '编码');
156	    state.filters.forEach(function (f) {
157	      html += chip('filt', filterLabel(f), f.id, f.src);
158	    });
159	    html += '<span class="chip anchor" title="认知锚点：跨维度切换与历史回退均保持">' +
160	      '◉ 选中 ' + state.sel.size + (hidden ? '（' + hidden + ' 被过滤遮蔽）' : '') + '</span>';
161	    if (state.pins.size) html += '<span class="chip anchor">★ 固定 ' + state.pins.size + '</span>';
162	    document.getElementById('chips').innerHTML = html;
163	
164	    document.querySelectorAll('#chips .chip[data-remove]').forEach(function (el) {
165	      el.addEventListener('click', function () {
166	        var t = el.getAttribute('data-remove');
167	        if (t === 'color') setEnc('color', null);
168	        else if (t === 'size') setEnc('size', null);
169	        else removeFilter(t);
170	      });
171	    });
172	
173	    document.getElementById('stateSummary').innerHTML =
174	      '显示 <b>' + vis.length + '</b> / ' + Data.rows.length + ' 条 · 过滤 <b>' + state.filters.length +
175	      '</b> · 视角「<b>' + esc(document.getElementById('lensName').value) + '</b>」';
176	  }
177	  function chip(kind, text, removeTarget, srcTag) {
178	    var h = '<span class="chip ' + kind + '" ' + (removeTarget ? 'data-remove="' + removeTarget + '" title="点击移除"' : '') + '>';
179	    if (srcTag) h += '<i class="src">' + esc(srcTag) + '</i>';
180	    h += esc(text);
181	    if (removeTarget) h += ' <b class="x">×</b>';
182	    return h + '</span>';
183	  }
184	
185	  /* ---------- 右栏：锚点与详情 ---------- */
186	  function recRow(r, isPin) {
187	    var cls = state.sel.has(r.id) ? ' rec-sel' : '';
188	    return '<div class="rec' + cls + '" data-id="' + r.id + '">' +
189	      '<span class="dot spec-' + r.spec + '"></span>' +
190	      '<span class="recname">' + esc(r.name) + '</span>' +
191	      '<span class="recmeta">' + esc(r.constel) + ' · ESI ' + r.esi.toFixed(2) + '</span>' +
192	      (isPin
193	        ? '<button class="unpin" data-unpin="' + r.id + '" title="取消固定">✕</button>'
194	        : '<button class="unpin" data-pin="' + r.id + '" title="固定">★</button>') +
195	      '</div>';
196	  }
197	  function renderSide() {
198	    var vis = visibleRows();
199	    var selVis = [], selGhost = [];
200	    vis.forEach(function (r) { if (state.sel.has(r.id)) selVis.push(r); });
201	    Data.rows.forEach(function (r) { if (state.sel.has(r.id) && vis.indexOf(r) < 0) selGhost.push(r); });
202	    selVis = selVis.slice(0, 40);
203	
204	    document.getElementById('anchorSummary').innerHTML =
205	      '<div class="acard"><b>' + state.sel.size + '</b> 选中<span>' +
206	      (selGhost.length ? selGhost.length + ' 条被当前过滤遮蔽，但仍保留' : '跨维度切换保持') +
207	      '</span></div>' +
208	      '<div class="acard"><b>' + state.pins.size + '</b> 固定<span>星标记录，任何状态变更不丢失</span></div>';
209	
210	    document.getElementById('selCount').textContent = state.sel.size;
211	    document.getElementById('selList').innerHTML = selVis.length || selGhost.length
212	      ? selVis.map(function (r) { return recRow(r, state.pins.has(r.id)); }).join('') +
213	        (selGhost.length ? '<div class="ghostline">…另有 ' + selGhost.length + ' 条被过滤遮蔽</div>' : '')
214	      : '<div class="empty">在图上拖拽框选记录</div>';
215	
216	    var pins = Data.rows.filter(function (r) { return state.pins.has(r.id); });
217	    document.getElementById('pinCount').textContent = pins.length;
218	    document.getElementById('pinList').innerHTML = pins.length
219	      ? pins.map(function (r) { return recRow(r, true); }).join('')
220	      : '<div class="empty">点击记录行的 ★ 固定</div>';
221	
222	    renderDetail();
223	    document.querySelectorAll('.rec').forEach(function (el) {
224	      el.addEventListener('click', function () { setDetail(el.getAttribute('data-id')); });
225	    });
226	    document.querySelectorAll('[data-pin]').forEach(function (el) {
227	      el.addEventListener('click', function (e) { e.stopPropagation(); togglePin(el.getAttribute('data-pin')); });
228	    });
229	    document.querySelectorAll('[data-unpin]').forEach(function (el) {
230	      el.addEventListener('click', function (e) { e.stopPropagation(); togglePin(el.getAttribute('data-unpin')); });
231	    });
232	  }
233	  function renderDetail() {
234	    var el = document.getElementById('detail');
235	    var r = Data.byId[detailId] || (state.sel.size
236	      ? Data.byId[state.sel.values().next().value] : null);
237	    if (!r) { el.innerHTML = ''; return; }
238	    var h = '<div class="panelhead"><h2>详情</h2></div><div class="dcard">' +
239	      '<h3><span class="dot spec-' + r.spec + '"></span>' + esc(r.name) + '</h3>' +
240	      '<table>';
241	    Data.NUMS.forEach(function (d) {
242	      h += '<tr><td>' + d.name + '</td><td><b>' + fmtV(d.key, r[d.key]) + '</b> ' + d.unit + '</td></tr>';
243	    });
244	    h += '<tr><td>恒星光谱型</td><td><b>' + r.spec + '</b></td></tr>';
245	    h += '<tr><td>探测方法</td><td><b>' + esc(r.method) + '</b></td></tr>';
246	    h += '<tr><td>宜居带</td><td><b>' + r.hz + '</b></td></tr>';
247	    h += '<tr><td>星座 / 天区</td><td><b>' + esc(r.constel) + '</b> / ' + esc(r.zone) + '</td></tr>';
248	    h += '</table>';
249	    // 关系：同系统行星
250	    var sib = Data.rows.filter(function (x) { return x.sysName === r.sysName && x.id !== r.id; });
251	    if (sib.length) {
252	      h += '<p class="sibhead">同系统行星</p><div class="sibs">';
253	      sib.forEach(function (x) {
254	        h += '<button class="sib" data-sib="' + x.id + '">' + esc(x.name) + '</button>';
255	      });
256	      h += '</div>';
257	    }
258	    h += '</div>';
259	    el.innerHTML = h;
260	    el.querySelectorAll('[data-sib]').forEach(function (b) {
261	      b.addEventListener('click', function () { setDetail(b.getAttribute('data-sib')); });
262	    });
263	  }
264	
265	  /* ---------- 历史抽屉 ---------- */
266	  function renderHist() {
267	    var drawer = document.getElementById('histDrawer');
268	    if (drawer.classList.contains('hidden')) return;
269	    var h = '';
270	    for (var i = hist.length - 1; i >= 0; i--) {
271	      var e = hist[i];
272	      h += '<li class="' + (i === hptr ? 'cur' : (i > hptr ? 'future' : '')) + '" data-i="' + i + '">' +
273	        '<span class="htime">' + e.t.toLocaleTimeString('zh-CN', { hour12: false }) + '</span>' +
274	        '<span class="hlabel">' + esc(e.label) + '</span>' +
275	        (i === hptr ? '<b class="htag">当前</b>' : '') + '</li>';
276	    }
277	    document.getElementById('histList').innerHTML = h;
278	    document.querySelectorAll('#histList li').forEach(function (li) {
279	      li.addEventListener('click', function () { jump(+li.getAttribute('data-i')); });
280	    });
281	  }
282	
283	  /* ---------- 自检（?selftest=1）：验收标准在页面内可见验证 ---------- */
284	  function selftest() {
285	    var out = [], pass = 0;
286	    function t(name, fn) {
287	      try { var v = fn(); out.push([v === true, name, v === true ? '' : String(v)]); if (v === true) pass++; }
288	      catch (e) { out.push([false, name, e.message]); }
289	    }
290	    var nAll = Data.rows.length;
291	    t('数据就绪：' + nAll + ' 条记录随首屏同步生成', function () { return nAll > 400; });
292	    t('数值维度完备：每条记录 11 个有限数值', function () {
293	      return Data.rows.every(function (r) {
294	        return Data.NUMS.every(function (d) { return isFinite(r[d.key]); });
295	      });
296	    });
297	    t('范围维度与数据一致', function () {
298	      return Data.NUMS.every(function (d) {
299	        var lo = Infinity, hi = -Infinity;
300	        Data.rows.forEach(function (r) { lo = Math.min(lo, r[d.key]); hi = Math.max(hi, r[d.key]); });
301	        return Math.abs(lo - Data.extents[d.key][0]) < 1e-9 && Math.abs(hi - Data.extents[d.key][1]) < 1e-9;
302	      });
303	    });
304	    t('初始无过滤：可见 = 全集', function () { return visibleRows().length === nAll; });
305	
306	    addRangeFilter('temp', 200, 650, '直方图框选');
307	    t('区间过滤生效：可见数 < 全集', function () { return visibleRows().length < nAll; });
308	    t('归属：过滤标签含维度名与谓词', function () {
309	      var f = state.filters[0];
310	      return filterLabel(f).indexOf('平衡温度') >= 0 && f.src === '直方图框选';
311	    });
312	    var selBefore = 14;
313	    setSel(visibleRows().slice(0, selBefore).map(function (r) { return r.id; }));
314	    t('框选 ' + selBefore + ' 条后选中数一致', function () { return state.sel.size === selBefore; });
315	
316	    setAxis('y', 'esi'); // 维度切换
317	    t('维度切换不重置认知：选中保持', function () { return state.sel.size === selBefore; });
318	    t('维度切换不重置认知：过滤保持', function () {
319	      return state.filters.length >= 1 && visibleRows().length < nAll;
320	    });
321	
322	    toggleCatFilter('hz', '是');
323	    t('类别过滤：勾掉「是」后不含该值', function () {
324	      return visibleRows().every(function (r) { return r.hz !== '是'; });
325	    });
326	    t('遮蔽归属：选中集含被过滤遮蔽的记录（不丢弃）', function () {
327	      var vis = visibleRows();
328	      return Array.from(state.sel).some(function (id) { return vis.map(function (r) { return r.id; }).indexOf(id) < 0; });
329	    });
330	
331	    var hBefore = hist.length;
332	    undo();
333	    t('撤销：回退一步后过滤减少', function () { return state.filters.length < 2 && hist.length === hBefore; });
334	    redo();
335	    t('重做：恢复到回退前状态', function () { return state.filters.length >= 2; });
336	    var label0 = hist[0].label;
337	    jump(0);
338	    t('时间线跳转：回到「' + label0 + '」', function () { return state.filters.length === 0; });
339	    t('历史节点均有标签与快照', function () {
340	      return hist.every(function (e) { return e.label && e.snap && 'x' in e.snap; });
341	    });
342	
343	    var panel = document.createElement('div');
344	    panel.id = 'selftest';
345	    var h = '<b>自检 selftest</b> — ' + pass + '/' + out.length + ' 通过' +
346	      (pass === out.length ? ' ✓' : ' ✗') + '<ul>';
347	    out.forEach(function (o) {
348	      h += '<li class="' + (o[0] ? 'ok' : 'bad') + '">' + (o[0] ? '✓' : '✗') + ' ' + esc(o[1]) +
349	        (o[2] ? ' <i>→ ' + esc(o[2]) + '</i>' : '') + '</li>';
350	    });
351	    panel.innerHTML = h + '</ul>';
352	    document.body.appendChild(panel);
353	  }
354	
355	  /* ---------- 初始化 ---------- */
356	  function init() {
357	    hist.push({ label: '初始状态', t: new Date(), snap: snap() });
358	    hptr = 0;
359	
360	    // ?demo=1：驱动一段真实交互（供截图取证）；?lens=名称 设视角名
361	    var qp = new URLSearchParams(location.search);
362	    if (qp.get('lens')) document.getElementById('lensName').value = qp.get('lens');
363	    if (qp.get('demo')) {
364	      addRangeFilter('temp', 200, 650, '直方图框选');
365	      toggleCatFilter('spec', 'M');
366	      var vs = visibleRows();
367	      setSel(vs.slice(0, 14).map(function (r) { return r.id; }));
368	      togglePin(vs[0].id); togglePin(vs[5].id);
369	      setAxis('y', 'esi');
370	      setTimeout(function () {
371	        document.getElementById('histDrawer').classList.remove('hidden'); render();
372	      }, 150);
373	    }
374	
375	    document.getElementById('datastat').innerHTML =
376	      '<b>' + Data.rows.length + '</b> 颗行星 · <b>' + Data.nStars + '</b> 个系统 · <b>' +
377	      Data.NUMS.length + '</b> 数值维 · <b>' + (Data.CATS.length + Data.HIER.length) + '</b> 类别维';
378	
379	    // 编码下拉：颜色=类别维度；大小=数值维度
380	    var cSel = document.getElementById('encColor'), sSel = document.getElementById('encSize');
381	    var oh = '<option value="">无</option>';
382	    Data.CATS.concat(Data.HIER).forEach(function (d) {
383	      oh += '<option value="' + d.key + '">' + d.name + '</option>';
384	    });
385	    cSel.innerHTML = oh;
386	    var osh = '<option value="">无</option>';
387	    Data.NUMS.forEach(function (d) { osh += '<option value="' + d.key + '">' + d.name + '</option>'; });
388	    sSel.innerHTML = osh;
389	    cSel.value = state.color; sSel.value = '';
390	    cSel.addEventListener('change', function () { setEnc('color', cSel.value || null); });
391	    sSel.addEventListener('change', function () { setEnc('size', sSel.value || null); });
392	
393	    document.getElementById('undoBtn').addEventListener('click', undo);
394	    document.getElementById('redoBtn').addEventListener('click', redo);
395	    document.getElementById('histBtn').addEventListener('click', function () {
396	      document.getElementById('histDrawer').classList.toggle('hidden'); render();
397	    });
