1	/* 星穹棱镜 · 维度货架：直方图框选过滤 + 投影轴指派 + 类别勾选 */
2	window.Shelf = (function () {
3	  'use strict';
4	  var SPW = 220, SPH = 34, BINS = 30;
5	
6	  function filterFor(dim) {
7	    return App.state.filters.filter(function (f) { return f.dim === dim; })[0] || null;
8	  }
9	
10	  /* ---------- 数值维度行 ---------- */
11	  function numRow(d) {
12	    var f = filterFor(d.key);
13	    var ext = Data.extents[d.key];
14	    var lo = ext[0], hi = ext[1];
15	    var bins = new Array(BINS).fill(0);
16	    Data.rows.forEach(function (r) {
17	      var i = Math.min(BINS - 1, Math.floor((r[d.key] - lo) / (hi - lo) * BINS));
18	      if (i >= 0) bins[i]++;
19	    });
20	    var bmax = Math.max.apply(null, bins);
21	    var bw = SPW / BINS;
22	    var bars = '';
23	    for (var i = 0; i < BINS; i++) {
24	      var bh = bmax ? bins[i] / bmax * (SPH - 6) : 0;
25	      var inF = !f || ((i + 0.5) / BINS * (hi - lo) + lo) >= f.lo && ((i + 0.5) / BINS * (hi - lo) + lo) <= f.hi;
26	      bars += '<rect x="' + (i * bw + 0.5).toFixed(1) + '" y="' + (SPH - bh).toFixed(1) +
27	        '" width="' + (bw - 1).toFixed(1) + '" height="' + bh.toFixed(1) +
28	        '" class="hb' + (inF ? '' : ' dim') + '"></rect>';
29	    }
30	    var overlay = '';
31	    if (f) {
32	      var x1 = (f.lo - lo) / (hi - lo) * SPW, x2 = (f.hi - lo) / (hi - lo) * SPW;
33	      overlay = '<rect class="frange" x="' + x1.toFixed(1) + '" y="0" width="' + (x2 - x1).toFixed(1) +
34	        '" height="' + SPH + '"></rect>';
35	    }
36	    var badge = f ? '<button class="fbadge" data-clearf="' + f.id + '" title="点击移除该维过滤">' +
37	      App.fmtV(d.key, f.lo) + '–' + App.fmtV(d.key, f.hi) + ' ✕</button>' : '';
38	    var onX = App.state.x === d.key, onY = App.state.y === d.key;
39	
40	    return '<div class="dim num' + (f ? ' filtered' : '') + '" data-dim="' + d.key + '">' +
41	      '<div class="dimrow"><span class="dname">' + d.name + '</span>' +
42	      '<span class="dunit">' + d.unit + '</span>' + badge +
43	      '<span class="spacer"></span>' +
44	      '<button class="ax' + (onX ? ' on' : '') + '" data-axis="x" data-dim="' + d.key + '">X</button>' +
45	      '<button class="ax' + (onY ? ' on' : '') + '" data-axis="y" data-dim="' + d.key + '">Y</button>' +
46	      '</div>' +
47	      '<svg class="spark" width="' + SPW + '" height="' + SPH + '" viewBox="0 0 ' + SPW + ' ' + SPH + '">' +
48	      bars + overlay +
49	      '<rect class="dragzone" x="0" y="0" width="' + SPW + '" height="' + SPH + '"></rect></svg>' +
50	      '<div class="dext">' + App.fmtV(d.key, lo) + ' – ' + App.fmtV(d.key, hi) + ' ' + d.unit + '</div>' +
51	      '</div>';
52	  }
53	
54	  /* ---------- 类别/层级维度行 ---------- */
55	  function catRow(d) {
56	    var counts = {};
57	    d.values.forEach(function (v) { counts[v] = 0; });
58	    Data.rows.forEach(function (r) { if (counts[r[d.key]] !== undefined) counts[r[d.key]]++; });
59	    var f = filterFor(d.key);
60	    var vals = '';
61	    d.values.forEach(function (v) {
62	      var on = App.catChecked(d.key, v);
63	      vals += '<button class="cv' + (on ? ' on' : ' off') + '" data-cat="' + d.key +
64	        '" data-val="' + App.esc(v) + '"><i class="cb"></i>' + App.esc(v) +
65	        '<em>' + counts[v] + '</em></button>';
66	    });
67	    return '<div class="dim cat' + (f ? ' filtered' : '') + '">' +
68	      '<div class="dimrow"><span class="dname">' + d.name + '</span>' +
69	      (f ? '<button class="fbadge" data-clearf="' + f.id + '" title="点击移除">含 ' + f.values.length + ' 值 ✕</button>' : '') +
70	      '</div><div class="catvals">' + vals + '</div></div>';
71	  }
72	
73	  /* ---------- 渲染 ---------- */
74	  function render() {
75	    var h = '';
76	    h += '<div class="dimgroup">数值维度（坐标轴 / 区间过滤）</div>';
77	    Data.NUMS.forEach(function (d) { h += numRow(d); });
78	    h += '<div class="dimgroup">类别与层级维度（勾选包含值）</div>';
79	    Data.CATS.forEach(function (d) { h += catRow(d); });
80	    Data.HIER.forEach(function (d) {
81	      h += catRow({ key: d.key, name: d.name, values: valuesOf(d.key) });
82	    });
83	    document.getElementById('dimList').innerHTML = h;
84	    document.getElementById('dimCount').textContent =
85	      Data.NUMS.length + ' 数值 · ' + (Data.CATS.length + Data.HIER.length) + ' 类别';
86	    wire();
87	  }
88	  function valuesOf(key) {
89	    var s = new Set();
90	    Data.rows.forEach(function (r) { s.add(r[key]); });
91	    return Array.from(s).sort();
92	  }
93	
94	  /* ---------- 交互 ---------- */
95	  function wire() {
96	    document.querySelectorAll('.ax').forEach(function (b) {
97	      b.addEventListener('click', function () { App.setAxis(b.getAttribute('data-axis'), b.getAttribute('data-dim')); });
98	    });
99	    document.querySelectorAll('.cv').forEach(function (b) {
100	      b.addEventListener('click', function () { App.toggleCatFilter(b.getAttribute('data-cat'), b.getAttribute('data-val')); });
101	    });
102	    document.querySelectorAll('[data-clearf]').forEach(function (b) {
103	      b.addEventListener('click', function () { App.removeFilter(b.getAttribute('data-clearf')); });
104	    });
105	    // 直方图拖拽 → 区间过滤（归属：直方图框选）
106	    document.querySelectorAll('.spark').forEach(function (svg) {
107	      var dim = svg.parentElement.getAttribute('data-dim');
108	      svg.addEventListener('mousedown', function (e) { startDrag(e, svg, dim); });
109	    });
110	  }
111	
112	  function startDrag(e, svg, dim) {
113	    e.preventDefault();
114	    var rect = svg.getBoundingClientRect();
115	    var ext = Data.extents[dim];
116	    var sx = e.clientX - rect.left;
117	    var ghost = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
118	    ghost.setAttribute('class', 'frange drag');
119	    ghost.setAttribute('y', 0);
120	    ghost.setAttribute('height', SPH);
121	    svg.appendChild(ghost);
122	    var moved = false;
123	
124	    function mv(ev) {
125	      var cx = Math.max(0, Math.min(SPW, ev.clientX - rect.left));
126	      moved = moved || Math.abs(cx - sx) > 2;
127	      var x1 = Math.min(sx, cx), x2 = Math.max(sx, cx);
128	      ghost.setAttribute('x', x1); ghost.setAttribute('width', Math.max(1, x2 - x1));
129	    }
130	    function up(ev) {
131	      document.removeEventListener('mousemove', mv);
132	      document.removeEventListener('mouseup', up);
133	      var cx = Math.max(0, Math.min(SPW, ev.clientX - rect.left));
134	      svg.removeChild(ghost);
135	      if (!moved) return; // 单击不设过滤
136	      var x1 = Math.min(sx, cx), x2 = Math.max(sx, cx);
137	      var lo = ext[0] + x1 / SPW * (ext[1] - ext[0]);
138	      var hi = ext[0] + x2 / SPW * (ext[1] - ext[0]);
139	      var f = App.state.filters.filter(function (g) { return g.dim === dim; })[0];
140	      if (f && Math.abs(lo - f.lo) < (ext[1] - ext[0]) * 0.002 && Math.abs(hi - f.hi) < (ext[1] - ext[0]) * 0.002) return;
141	      App.addRangeFilter(dim, lo, hi, '直方图框选');
142	    }
143	    document.addEventListener('mousemove', mv);
144	    document.addEventListener('mouseup', up);
145	  }
146	
147	  return { render: render };
148	})();
149

