1	/* 星穹棱镜 · 主屏散点：投影轴 / 编码 / 框选 / 遮蔽幽灵点（认知连续性） */
2	window.Plot = (function () {
3	  'use strict';
4	  var M = { l: 58, r: 18, t: 12, b: 42 };
5	  var SVG_NS = 'http://www.w3.org/2000/svg';
6	
7	  var SPEC_COLORS = { M: '#e0566e', K: '#f0975a', G: '#e8d44d', F: '#f2f0e6', A: '#8ecdf5', B: '#7a8ef5' };
8	  var PALETTE = ['#5ab4f0', '#f0975a', '#67d98b', '#e0566e', '#c084fc', '#e8d44d', '#4fd8c8', '#f272a8'];
9	
10	  function colorFor(dimKey, val) {
11	    if (dimKey === 'spec') return SPEC_COLORS[val] || '#999';
12	    var d = App.dimByKey(dimKey);
13	    var vals = d.values || catValues(dimKey);
14	    return PALETTE[Math.max(0, vals.indexOf(val)) % PALETTE.length];
15	  }
16	  function catValues(key) {
17	    var s = new Set();
18	    Data.rows.forEach(function (r) { s.add(r[key]); });
19	    return Array.from(s).sort();
20	  }
21	
22	  /* ---------- 比例尺：跨度大自动对数 ---------- */
23	  function makeScale(dim, a0, a1) {
24	    var ext = Data.extents[dim];
25	    var log = ext[0] > 0 && ext[1] / ext[0] > 300;
26	    var d0 = log ? Math.log10(Math.max(ext[0], 1e-3)) : ext[0];
27	    var d1 = log ? Math.log10(ext[1]) : ext[1];
28	    function to(v) {
29	      var t = (log ? Math.log10(Math.max(v, 1e-3)) : v) - d0;
30	      return a0 + t / (d1 - d0) * (a1 - a0);
31	    }
32	    function inv(px) {
33	      var t = (px - a0) / (a1 - a0) * (d1 - d0) + d0;
34	      return log ? Math.pow(10, t) : t;
35	    }
36	    return { to: to, inv: inv, log: log, d0: d0, d1: d1, ext: ext };
37	  }
38	  function ticks(sc, n) {
39	    var out = [];
40	    if (sc.log) {
41	      for (var e = Math.ceil(sc.d0); e <= Math.floor(sc.d1); e++) out.push(Math.pow(10, e));
42	      if (out.length < 2) out = [Math.pow(10, sc.d0), Math.pow(10, sc.d1)];
43	      return out;
44	    }
45	    var span = sc.d1 - sc.d0, step = Math.pow(10, Math.floor(Math.log10(span / n)));
46	    var err = span / n / step;
47	    if (err >= 7.5) step *= 10; else if (err >= 3.5) step *= 5; else if (err >= 1.5) step *= 2;
48	    for (var v = Math.ceil(sc.d0 / step) * step; v <= sc.d1 + 1e-9; v += step) out.push(+v.toFixed(6));
49	    return out;
50	  }
51	  function fmtTick(v) {
52	    if (Math.abs(v) >= 1000) return (v / 1000) + 'k';
53	    if (Math.abs(v) >= 10) return String(Math.round(v));
54	    return String(+v.toFixed(1));
55	  }
56	
57	  /* ---------- 渲染 ---------- */
58	  function render() {
59	    var svg = document.getElementById('plot');
60	    var wrap = document.getElementById('plotwrap');
61	    var W = wrap.clientWidth || 900, H = wrap.clientHeight || 560;
62	    svg.setAttribute('width', W); svg.setAttribute('height', H);
63	    svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
64	    var st = App.state;
65	    var vis = App.visibleRows();
66	    var selGhost = [];
67	    Data.rows.forEach(function (r) { if (st.sel.has(r.id) && vis.indexOf(r) < 0) selGhost.push(r); });
68	
69	    var iw = W - M.l - M.r, ih = H - M.t - M.b;
70	    var sx = makeScale(st.x, M.l, M.l + iw);
71	    var sy = makeScale(st.y, M.t + ih, M.t); // y 反向
72	
73	    var s = '<rect id="plotbg" x="' + M.l + '" y="' + M.t + '" width="' + iw + '" height="' + ih + '" fill="transparent"/>';
74	    // 网格 + 刻度
75	    ticks(sx, 6).forEach(function (v) {
76	      var x = sx.to(v);
77	      s += '<line x1="' + x + '" y1="' + M.t + '" x2="' + x + '" y2="' + (M.t + ih) + '" class="gridl"/>' +
78	        '<text x="' + x + '" y="' + (H - M.b + 16) + '" class="tick" text-anchor="middle">' + fmtTick(v) + '</text>';
79	    });
80	    ticks(sy, 5).forEach(function (v) {
81	      var y = sy.to(v);
82	      s += '<line x1="' + M.l + '" y1="' + y + '" x2="' + (M.l + iw) + '" y2="' + y + '" class="gridl"/>' +
83	        '<text x="' + (M.l - 8) + '" y="' + (y + 4) + '" class="tick" text-anchor="end">' + fmtTick(v) + '</text>';
84	    });
85	    var dx = App.dimByKey(st.x), dy = App.dimByKey(st.y);
86	    s += '<text x="' + (M.l + iw / 2) + '" y="' + (H - 8) + '" class="axisname" text-anchor="middle">' +
87	      dx.name + (dx.unit ? ' (' + dx.unit + ')' : '') + (sx.log ? ' · 对数轴' : '') + '</text>';
88	    s += '<text x="' + (M.l - 44) + '" y="' + (M.t + ih / 2) + '" class="axisname" text-anchor="middle" transform="rotate(-90 ' + (M.l - 44) + ' ' + (M.t + ih / 2) + ')">' +
89	      dy.name + (dy.unit ? ' (' + dy.unit + ')' : '') + (sy.log ? ' · 对数轴' : '') + '</text>';
90	
91	    // 大小编码
92	    var sizeSc = null;
93	    if (st.size) {
94	      var e2 = Data.extents[st.size];
95	      sizeSc = function (v) { return 2 + 4.5 * (v - e2[0]) / (e2[1] - e2[0]); };
96	    }
97	
98	    // 遮蔽幽灵点（选中但被过滤遮蔽 —— 认知锚）
99	    selGhost.forEach(function (r) {
100	      s += pt(r, sx, sy, sizeSc, ' ghostpt');
101	    });
102	    // 可见点
103	    vis.forEach(function (r) {
104	      var cls = 'pt' + (st.sel.has(r.id) ? ' sel' : '') + (App.state.pins.has(r.id) ? ' pinned' : '');
105	      s += pt(r, sx, sy, sizeSc, ' ' + cls);
106	    });
107	    // 固定星标
108	    vis.forEach(function (r) {
109	      if (st.pins.has(r.id)) {
110	        s += '<text class="pinstar" x="' + (sx.to(r[st.x]) + 6) + '" y="' + (sy.to(r[st.y]) - 6) + '">★</text>';
111	      }
112	    });
113	
114	    s += '<rect id="brushbox" class="hidden" x="0" y="0" width="0" height="0"/>';
115	    svg.innerHTML = s;
116	
117	    document.getElementById('plotTitle').innerHTML = dx.name + ' <i>×</i> ' + dy.name +
118	      ' <span class="plotmeta">显示 ' + vis.length + ' 条' + (sx.log ? ' · X 对数' : '') + (sy.log ? ' · Y 对数' : '') + '</span>';
119	
120	    renderLegend(vis);
121	    wire(svg, sx, sy, vis);
122	  }
123	
124	  function pt(r, sx, sy, sizeSc, cls) {
125	    var x = sx.to(r[App.state.x]), y = sy.to(r[App.state.y]);
126	    var rad = sizeSc ? sizeSc(r[App.state.size]) : 3.2;
127	    var fill = App.state.color ? colorFor(App.state.color, r[App.state.color]) : '#5ab4f0';
128	    var h = '<circle cx="' + x.toFixed(1) + '" cy="' + y.toFixed(1) + '" r="' + rad.toFixed(1) +
129	      '" fill="' + fill + '" class="' + cls.trim() + '" data-id="' + r.id + '">';
130	    h += '<title>' + App.esc(r.name) + '\n' + App.dimByKey(App.state.x).name + ': ' + App.fmtV(App.state.x, r[App.state.x]) +
131	      ' · ' + App.dimByKey(App.state.y).name + ': ' + App.fmtV(App.state.y, r[App.state.y]) +
132	      '\nESI ' + r.esi.toFixed(2) + ' · ' + App.esc(r.constel) + ' · ' + App.esc(r.method) + '</title>';
133	    return h + '</circle>';
134	  }
135	
136	  function renderLegend(vis) {
137	    var el = document.getElementById('legend');
138	    if (!App.state.color) { el.innerHTML = ''; return; }
139	    var d = App.dimByKey(App.state.color);
140	    var vals = d.values || catValues(App.state.color);
141	    var counts = {};
142	    vis.forEach(function (r) { counts[r[App.state.color]] = (counts[r[App.state.color]] || 0) + 1; });
143	    var h = '<b>' + d.name + '</b>';
144	    vals.slice(0, 9).forEach(function (v) {
145	      if (!counts[v]) return;
146	      h += '<span class="lg"><i style="background:' + colorFor(App.state.color, v) + '"></i>' +
147	        App.esc(v) + ' <em>' + counts[v] + '</em></span>';
148	    });
149	    if (vals.length > 9) h += '<span class="lg">…</span>';
150	    el.innerHTML = h;
151	  }
152	
153	  /* ---------- 交互：悬停 / 点击选中 / 拖拽框选 ---------- */
154	  function wire(svg, sx, sy) {
155	    var bg = svg.querySelector('#plotbg');
156	    var box = svg.querySelector('#brushbox');
157	    var shift = false;
158	
159	    svg.querySelectorAll('circle.pt').forEach(function (c) {
160	      c.addEventListener('click', function (e) {
161	        e.stopPropagation();
162	        App.toggleSel(c.getAttribute('data-id'));
163	        App.setDetail(c.getAttribute('data-id'));
164	      });
165	    });
166	
167	    function pos(ev) {
168	      var r = svg.getBoundingClientRect();
169	      return [ev.clientX - r.left, ev.clientY - r.top];
170	    }
171	    bg.addEventListener('mousedown', function (e) {
172	      if (e.target !== bg) return;
173	      shift = e.shiftKey;
174	      var p0 = pos(e), active = true;
175	      box.classList.remove('hidden');
176	
177	      function mv(ev) {
178	        var p1 = pos(ev);
179	        box.setAttribute('x', Math.min(p0[0], p1[0]));
180	        box.setAttribute('y', Math.min(p0[1], p1[1]));
181	        box.setAttribute('width', Math.abs(p1[0] - p0[0]));
182	        box.setAttribute('height', Math.abs(p1[1] - p0[1]));
183	      }
184	      function up(ev) {
185	        document.removeEventListener('mousemove', mv);
186	        document.removeEventListener('mouseup', up);
187	        box.classList.add('hidden');
188	        if (!active) return; active = false;
189	        var p1 = pos(ev);
190	        var x0 = Math.min(p0[0], p1[0]), x1 = Math.max(p0[0], p1[0]);
191	        var y0 = Math.min(p0[1], p1[1]), y1 = Math.max(p0[1], p1[1]);
192	        if (x1 - x0 < 4 && y1 - y0 < 4) { if (!shift) App.clearSel(); return; } // 单击空白清除
193	        var vx0 = sx.inv(x0), vx1 = sx.inv(x1);
194	        var vy0 = sy.inv(y1), vy1 = sy.inv(y0);
195	        var ids = [];
196	        App.visibleRows().forEach(function (r) {
197	          var vx = r[App.state.x], vy = r[App.state.y];
198	          if (vx >= vx0 && vx <= vx1 && vy >= vy0 && vy <= vy1) ids.push(r.id);
199	        });
200	        if (shift) { ids.forEach(function (id) { if (!App.state.sel.has(id)) App.state.sel.add(id); }); App.render(); }
201	        else App.setSel(ids);
202	        if (ids.length) App.setDetail(ids[0]);
203	      }
204	      document.addEventListener('mousemove', mv);
205	      document.addEventListener('mouseup', up);
206	    });
207	  }
208	
209	  window.addEventListener('resize', function () { if (window.App) App.render(); });
210	
211	  return { render: render };
212	})();
