  var SVG_NS = 'http://www.w3.org/2000/svg';

  var SPEC_COLORS = { M: '#e0566e', K: '#f0975a', G: '#e8d44d', F: '#f2f0e6', A: '#8ecdf5', B: '#7a8ef5' };
  var PALETTE = ['#5ab4f0', '#f0975a', '#67d98b', '#e0566e', '#c084fc', '#e8d44d', '#4fd8c8', '#f272a8'];

  function colorFor(dimKey, val) {
